sketches.source:
setcpm(150/4)

// The arrangement: a quiet intro, the break twice with a different ending each pass,
// a primed reprise and a stop. About a minute and three quarters.
song("intro@4 (break@16 1.drop@4 2.glitch@4)*2 break'@16 outro@4", "once")

// One break, mangled differently almost every bar; in the primed reprise it also runs backwards
const brk = s("bd ~ [~ bd] ~ sd ~ bd sd, hh*16")
drums: brk.someCyclesBy(.5, x => x.scramble(16)).sometimesBy(.25, x => x.ply("<2 3 4>"))
  .chunk(4, x => x.hurry(2)).crush("<16 8 4 6>").seed("gremlin").gain(.6)
  .sections("break glitch").variant(x => x.rev())

// A bass ring-modulated into a gargling metal lump, out for the intro and the outro
bass: note("c2 ~ c2 eb2 ~ c2 gb2 ~").s("sawtooth").ringmod(sine.range(30, 400).slow(4)).ringmix(.6)
  .lpf(1200).decay(.15).sustain(.3).release(.05).gain(.4)
  .exceptSections("intro outro")

// Clicks at random speeds that run backwards in random bars, all the way through
clicks: s("click*16?0.5").speed(rand.range(.5, 3)).someCycles(x => x.rev())
  .pan(rand).seed("sprocket").gain(.15)

// A frequency-shifted bell: every partial moves by the same hertz, so no key survives
bells: note("<c5 gb5 a4 eb5>").s("sine").fm(4).fmh(1.41).fshift("<0 37 -113 250>")
  .decay(.4).sustain(0).delay(.3).delaytime(3/16).delayfeedback(.5).gain(.14)
  .sections("intro drop glitch outro")

setcpm(70/4)

// Hum, choir, robot, choir again, and the plate going round on its own at the end
song("intro@4 choir@8 robot@8 choir'@8 coda@4", "once")

// A choir ring-modulated at 220 Hz, its partials sliding back and forth by a few hertz,
// singing more quietly in the coda
choir: note("<[c3,e3,g3] [ab2,c3,eb3] [f2,a2,c3] [g2,b2,d3]>").s("choir")
  .syl("<ah oo ee oh>").ringmod(220).ringmix(.4).fshift(sine.range(-60, 60).slow(8))
  .attack(1).release(2).space("church").gain(bysec("coda:.15 *:.3"))
  .exceptSections("intro")

// A robot tenor: the spectral robot effect flattens every partial onto one pitch
robot: note("<c4 ab3 a3 b3>").s("voice").syl("<beep boop bip bop>").voicetype("tenor")
  .spectral("robot").samount(.8).mono(1).vglide(.05).gain(.28)
  .sections("robot choir'")

// The turntable hum never stops
hum: s("engine").slow(8).lpf(300).gain(.12)

// The timer: every section restarts at bar zero, so three dings land on the eighth bar of each
ding: note("<~ ~ ~ ~ ~ ~ ~ [c6 c6 c6 ~]>").s("sine").fm(3).fmh(3.5)
  .decay(1.2).sustain(0).release(1).room(.4).gain(.2)
  .sections("choir robot")

setcpm(66/4)

// An opera in five scenes, with a dying ritardando over the finale
song("overture@4 aria@8 duet@8 aria'@8 finale@4", "once")
tempomap("0:16.5 28:16.5 32:12")

// The diva: mi_a_u glides across three vowels in one note, scooping up into each.
// In the primed aria she reprises it an octave higher.
diva: note("<[g4@3 c5] [e5@2 d5 c5] [a5@4] [g5@2 ~@2]>")
  .s("voice").syl("mi_a_u").voicetype("soprano").scoop(-7).jitter(.5)
  .mono(1).vglide(.15).attack(.1).release(.8).space("hall").gain(.3)
  .exceptSections("overture").variant(x => x.add(12))

// The tomcat answers from the fence, gravelly, off to the left
tom: note("<~ [c3@2 g2@2] ~ [eb3@3 c3]>").s("voice").syl("ma_o").voicetype("tenor").fry(.6)
  .mono(2).vglide(.2).release(.6).azimuth(-60).distance(3).gain(.26)
  .sections("duet aria'")

// The orchestra plucks along inside a violin body
pizz: note("<[c3 e3 g3 e3] [f3 a3 c4 a3] [d3 f3 a3 f3] [g3 b3 d4 b3]>").s("triangle").timbre("bright")
  .decay(.15).sustain(0).body("violin").bodymix(.3).room(.4).gain(.2)

// The purr: a low saw trembling twenty-five times a second
purr: note("c1").slow(4).s("sawtooth").lpf(200).trem(25).tremdepth(.8)
  .attack(1).sustain(1).release(1).gain(.12)

setcpm(220/4)

// Two rounds of polka, broken first by an alarm and then by panic, a last round and the apocalypse
song("intro@8 (polka@16 1.alarm@8 2.panic@8)*2 polka'@24 apocalypse@8", "once")
// Steady at 220 BPM, then accelerating into the apocalypse
tempomap("0:55 80:55 88:70")

// One function for the whole band: on the last bar of every section, everything rushes twice as fast
const polka = (x) => x.atEnd(1, y => y.hurry(2))

// Accordion oom-pah: two reeds tuned apart, through an a vowel
oompah: note("<[c2 [e3,g3] g1 [e3,g3]] [g1 [d3,f3,b3] d2 [d3,f3,b3]]>")
  .s("sawtooth").timbre("reed").unison(2).detune(16).vowel("a").lpf(2000)
  .decay(.15).sustain(.3).release(.05).polka().gain(.3)

// The tune, far too cheerful, and an octave higher still in the last round
tune: note("<[e5 g5 e5 c5] [d5 f5 d5 b4] [e5 g5 c6 g5] [d5@2 c5@2]>")
  .s("sawtooth").timbre("reed").vowel("e").lpf(3000).attack(.01).sustain(.6).release(.05)
  .polka().gain(.22).sections("polka panic").variant(x => x.add(12))

drums: s("bd sd bd sd, hh*8").polka().gain(.45).exceptSections("intro")

// Meanwhile, the sky is falling: an air-raid siren gliding up and down
siren: freq(sine.range(500, 1100).slow(2).segment(16)).s("sine").mono(1).glide(.12)
  .attack(.01).sustain(1).release(.05).gain(.06)
  .sections("alarm panic apocalypse")

// And a rumble that darkens and swells once over the whole song
rumble: s("brown*4").lpf(env("100 1200", "song")).gain(env(".02 .2", "song"))
  .attack(.05).release(.1)

setcpm(120/4)

// The swarm arrives, buzzes, gathers, stings and leaves
song("arrive@8 buzz@16 swarm@16 sting@8 leave@4", "once")

// The swarm: one bee circles once a bar, one the other way every two bars, one darts at random
bee1: s("insect*8").azimuth(saw.range(-180, 180)).elevation(20).distance(1).posglide(.1).gain(.18)
bee2: s("insect*8").azimuth(isaw.range(-180, 180).slow(2)).elevation(-10).distance(1.5).posglide(.1).gain(.14)
  .exceptSections("arrive")
bee3: s("insect*16").azimuth(rand.range(-180, 180)).elevation(rand.range(-40, 60))
  .distance(.7).posglide(.05).seed("sting").gain(.1)
  .sections("swarm sting")

// Hats lean right, and a seeded coin flip sends some of them to the left
hats: s("hh*16").hpf(7000).ild(10).earswap(irand(2).segment(16)).seed("hop").gain(.25)
  .exceptSections("arrive leave")

// The phase between the ears turns half a time, once, twice, then almost three times a second,
// one step per section, and calms down again as the swarm leaves
drone: note("[e2,b2]").s("sawtooth").irate(bysec("buzz:1 swarm:2 sting:2.9 *:.5")).lpf(800)
  .attack(1).sustain(1).release(1).gain(.18)

// The kick: the only thing left in the middle of your head, with a stutter before each new section
kick: s("bd*4").shape(.2).gain(.6).exceptSections("arrive leave").atEnd(1, x => x.ply(2))

setcpm(80/4)

// One theme and three primed variations, then a plain coda with a ritardando
song("theme@8 theme'@8 theme''@8 theme'''@8 coda@4", "once")
tempomap("0:20 32:20 36:14")

// One innocent piano phrase
const phrase = n("<[0 2 4 7] [5 4 2 0] [3 5 7 9] [7@2 4 2]>").scale("F:major").transpose(12)
  .s("triangle").timbre("soft").decay(.6).sustain(.1).release(.6)

// Plain, then one prime: frozen into a smear, two: blurred into fog, three: combed into metal at 110 Hz
piano: phrase.variant(
  x => x.spectral("freeze").samount(.9),
  x => x.spectral("blur").samount(.8),
  x => x.spectral("comb").scomb(110).samount(.7)).room(.5).gain(.26)

// The bass, shifted up a fourth, then down a fifth, then flattened into a robot
bass: note("<f2 d2 bb1 c2>").variant(
  x => x.spectral("shift").sshift(5).samount(1),
  x => x.spectral("shift").sshift(-7).samount(1),
  x => x.spectral("robot").samount(1))
  .s("sawtooth").lpf(800).attack(.05).sustain(.7).release(.3).gain(.25)

// The drums keep time through the wreckage and sit out the coda
drums: s("bd ~ ~ bd, ~ rim ~ rim").gain(.35).sections("theme")

setcpm(110/4)

// Dawn, breakfast, the kettle, more breakfast, and the toast
song("dawn@4 breakfast@16 kettle@8 breakfast'@12 toast@4", "once")

// A saw bass with something to say: talk puts a syllable track on it.
// After the kettle it has more to say, an octave up.
bass: note("c2 c2 eb2 c2 g1 c2 bb1 c2").s("sawtooth")
  .syl("<[wa wa wo wi] [ya ya yo yu] [ba ba bo bi] [na na no neng]>").talk(1)
  .lpf(2400).decay(.2).sustain(.4).gain(.35)
  .exceptSections("dawn toast").variant(x => x.add(12))

// A crunchy, swung breakfast beat, with a doubled fill at the end of each section
drums: s("bd ~ [~ bd] ~, ~ sd ~ sd, hh*8").swing(4).crush(10).gain(.45)
  .sections("breakfast kettle").atEnd(1, x => x.ply(2))

// The radio mutters in the corner all morning
radio: s("whisper*8?0.5").syl("<sha ko ta ri>").crush(4).hpf(1000).seed("static").pan(.8).gain(.14)

// The kettle works up to a whistle over its whole section
kettle: note("c7").s("sine").vib(8).vibdepth(.3).attack(1).sustain(1).release(.5)
  .gain(env("0 .06", "section")).sections("kettle")

// The toaster pops once, and the robot announces it: toast is ready
pop: s("<[click ~ ~ ~] ~ ~ ~>").speed(.5).gain(.5).sections("toast")
robot: note("<c4 eb4 g4 bb4>").s("voice").syl("<toast is re_a dee>").voicetype("bass")
  .spectral("robot").samount(.7).mono(1).vglide(.04).gain(.26)
  .sections("toast")
